### 🔹 Code: Optimized Bubble Sort
```c
#include <stdio.h>

void bubble_sort(int arr[], int n) {
    for(int i = 0; i < n-1; i++) {
        int swapped = 0; // flag to check if swapping happened

        for(int j = 0; j < n-i-1; j++) {
            if(arr[j] > arr[j+1]) {
                int temp = arr[j];
                arr[j] = arr[j+1];
                arr[j+1] = temp;
                swapped = 1;
            }
        }

        // If no elements were swapped in this pass, break
        if(swapped == 0) {
            break;
        }
    }
}

int main() {
    int arr[] = {5, 1, 4, 2, 8};
    int n = sizeof(arr)/sizeof(arr[0]);

    printf("Original array: ");
    for(int i=0; i<n; i++) printf("%d ", arr[i]);
    printf("\n");

    bubble_sort(arr, n);

    printf("Sorted array: ");
    for(int i=0; i<n; i++) printf("%d ", arr[i]);
    printf("\n");

    return 0;
}
```

---

✅ **Time Complexity:**  
- Worst case: **O(n²)**  
- Best case (already sorted): **O(n)** due to optimization.  

